// HasAssignment applies the HasEdge predicate on the "assignment" edge.
func HasAssignment() predicate.ProofOfDelivery {
	return predicate.ProofOfDelivery(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, AssignmentTable, AssignmentColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAssignmentWith applies the HasEdge predicate on the "assignment" edge with a given conditions (other predicates).
func HasAssignmentWith(preds ...predicate.OrderAssignment) predicate.ProofOfDelivery {
	return predicate.ProofOfDelivery(func(s *sql.Selector) {
		step := newAssignmentStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ProofOfDelivery) predicate.ProofOfDelivery {
	return predicate.ProofOfDelivery(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ProofOfDelivery) predicate.ProofOfDelivery {
	return predicate.ProofOfDelivery(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ProofOfDelivery) predicate.ProofOfDelivery {
	return predicate.ProofOfDelivery(sql.NotPredicates(p))
}
